54	// checkLatestB 完整核对 S-B 的返回内容。
55	// S-B：pH 7 ≤ 8、COD 20 ≤ 30，两项与整份均达标。
56	func checkLatestB(t *testing.T, smp Sample, sampled time.Time, label string) {
57		t.Helper()
