86	
87	// 同一采样点 S-A、S-B 在同一瞬间采样且均已确认，测量值与判定依据不同。
88	// 无论录入先后、确认先后（包括 S-A 最后才办理确认），也无论两份各用
89	// UTC 还是北京时间表示同一瞬间，最近有效结果都必须按编号升序选中 S-A，
90	// 且返回内容整体来自 S-A。
91	func TestLatestResultSameInstantConfirmedTieBreak(t *testing.T) {
92		t0 := latestBaseTime()
93		beijing := time.FixedZone("CST", 8*3600)
94		t0Beijing := time.Date(2026, 9, 10, 8, 0, 0, 0, beijing) // 与 t0 同一瞬间
95		aMs := []Measurement{{Item: "pH", Value: 9}, {Item: "COD", Value: 30}}
96		bMs := []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 20}}
97	
98		cases := []struct {
99			name string
100			// 每份样品用什么时区表示采样瞬间（两者必须是同一瞬间）
101			aAt, bAt time.Time
102			// 录入与确认的编号顺序
103			submitOrder  []string
104			confirmOrder []string
105		}{
106			{
107				name: "S-B 最后录入且最后确认",
108				aAt:  t0, bAt: t0,
109				submitOrder:  []string{"S-A", "S-B"},
110				confirmOrder: []string{"S-A", "S-B"},
111			},
112			{
113				name: "S-A 最后录入且最后确认",
114				aAt:  t0, bAt: t0,
115				submitOrder:  []string{"S-B", "S-A"},
116				confirmOrder: []string{"S-B", "S-A"},
117			},
118			{
119				name: "录入与确认顺序交叉",
120				aAt:  t0, bAt: t0,
121				submitOrder:  []string{"S-A", "S-B"},
122				confirmOrder: []string{"S-B", "S-A"},
123			},
124			{
125				name: "S-A 用 UTC、S-B 用北京时间表示同一瞬间",
126				aAt:  t0, bAt: t0Beijing,
127				submitOrder:  []string{"S-B", "S-A"},
128				confirmOrder: []string{"S-B", "S-A"},
129			},
130			{
131				name: "S-A 用北京时间、S-B 用 UTC 表示同一瞬间",
132				aAt:  t0Beijing, bAt: t0,
133				submitOrder:  []string{"S-A", "S-B"},
134				confirmOrder: []string{"S-A", "S-B"},
135			},
136		}
137	
138		for _, c := range cases {
139			t.Run(c.name, func(t *testing.T) {
140				s, _ := open(t)
141				mustPoint(t, s, "P1", "取水口")
142				mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
143				mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
144	
145				for _, id := range c.submitOrder {
146					if id == "S-A" {
147						mustSample(t, s, "S-A", "P1", c.aAt, aMs...)
148					} else {
149						mustSample(t, s, "S-B", "P1", c.bAt, bMs...)
150					}
151				}
152				for _, id := range c.confirmOrder {
153					if _, err := s.Confirm(id); err != nil {
154						t.Fatalf("Confirm %s: %v", id, err)
155					}
156				}
157	
158				latest, ok, err := s.LatestResult("P1")
159				if err != nil || !ok {
160					t.Fatalf("最近有效结果应为 S-A: %+v ok=%v err=%v", latest, ok, err)
161				}
162				checkLatestA(t, latest, "最近有效结果")
163			})
164		}
165	}
166	
167	// 实际采样时刻只差一纳秒时，必须选择真正较晚的那份（S-B），
168	// 即使它的编号排在 S-A 后面；编号升序只在时刻完全相同时才生效。
169	// 较早的 S-A 最后确认也不能把它顶成最近结果。
170	func TestLatestResultNanosecondLaterWins(t *testing.T) {
171		t0 := latestBaseTime()
172		tLater := t0.Add(1) // 仅晚一纳秒
173	
174		cases := []struct {
175			name         string
176			confirmOrder []string
177		}{
178			{"较晚的 S-B 最后确认", []string{"S-A", "S-B"}},
179			{"较早的 S-A 最后确认", []string{"S-B", "S-A"}},
180		}
181		for _, c := range cases {
182			t.Run(c.name, func(t *testing.T) {
183				s, _ := open(t)
184				mustPoint(t, s, "P1", "取水口")
185				mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
186				mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
187				mustSample(t, s, "S-A", "P1", t0,
188					Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
189				mustSample(t, s, "S-B", "P1", tLater,
190					Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 20})
191				for _, id := range c.confirmOrder {
192					if _, err := s.Confirm(id); err != nil {
193						t.Fatalf("Confirm %s: %v", id, err)
194					}
195				}
196	
197				latest, ok, err := s.LatestResult("P1")
198				if err != nil || !ok {
199					t.Fatalf("最近有效结果应为晚一纳秒的 S-B: %+v ok=%v err=%v", latest, ok, err)
200				}
201				checkLatestB(t, latest, tLater, "晚一纳秒的最近有效结果")
202			})
203		}
204	}
205	
206	// 采样更晚的待判定样品、确认后又作废（仍保留完整判定依据）的样品，
207	// 以及其他采样点的更晚结果，都不能抢占当前采样点的最近有效结果。
208	// 同时刻选中的 S-A 作废后，应退到该时刻下一份仍有效的已确认样品 S-B；
209	// 全部失效后明确无结果，不能把待判定记录的超标零值当成达标。
210	func TestLatestResultExcludesPendingVoidedAndOtherPoints(t *testing.T) {
211		s, dir := open(t)
212		mustPoint(t, s, "P1", "取水口")
213		mustPoint(t, s, "P2", "排水口")
214		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
215		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
216		mustLimit(t, s, "P2", "pH", 8.0, at(1, 0))
217	
218		t0 := latestBaseTime()
219		// S-A、S-B 同一时刻均已确认；S-A 编号在前且整份超标，S-B 达标。
220		mustSample(t, s, "S-A", "P1", t0,
221			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
222		mustSample(t, s, "S-B", "P1", t0,
223			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 20})
224		// S-C 采样更晚但始终待判定（测量值超标也没有结论）。
225		mustSample(t, s, "S-C", "P1", t0.Add(time.Hour),
226			Measurement{Item: "pH", Value: 12}, Measurement{Item: "COD", Value: 40})
227		// S-D 采样更晚、已确认后再作废，作废后仍保留完整判定依据。
228		mustSample(t, s, "S-D", "P1", t0.Add(2*time.Hour),
229			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
230		// 另一采样点的更晚已确认结果。
231		mustSample(t, s, "S-X", "P2", t0.Add(24*time.Hour), Measurement{Item: "pH", Value: 7})
232		for _, id := range []string{"S-B", "S-D", "S-A", "S-X"} {
233			if _, err := s.Confirm(id); err != nil {
234				t.Fatalf("Confirm %s: %v", id, err)
235			}
236		}
237		if _, err := s.Void("S-D", "复测确认超标"); err != nil {
238			t.Fatalf("Void S-D: %v", err)
239		}
240	
241		// 更晚的待判定、更晚的作废、其他点的更晚结果都不能抢占：仍是 S-A。
242		latest, ok, err := s.LatestResult("P1")
243		if err != nil || !ok {
244			t.Fatalf("最近有效结果应为 S-A: %+v ok=%v err=%v", latest, ok, err)
245		}
246		checkLatestA(t, latest, "存在更晚无效记录时")
247		// 其他采样点查它自己的更晚结果，互不串点。
248		if other, ok, err := s.LatestResult("P2"); err != nil || !ok || other.ID != "S-X" {
249			t.Fatalf("P2 的最近有效结果应为 S-X: %+v ok=%v err=%v", other, ok, err)
250		}
251	
252		// 作废记录的完整判定依据仍保留在按点列表里，但不能因此再次成为有效结果。
253		list, err := s.ListByPoint("P1")
254		if err != nil || len(list) != 4 {
255			t.Fatalf("ListByPoint: %+v err=%v", list, err)
256		}
257		find := func(id string) Sample {
258			t.Helper()
259			for _, smp := range list {
260				if smp.ID == id {
261					return smp
262				}
263			}
264			t.Fatalf("列表中缺少 %s: %+v", id, list)
265			return Sample{}
266		}
267		d := find("S-D")
268		if d.Status != StatusVoided || d.VoidReason != "复测确认超标" || !d.Exceeded || len(d.Results) != 2 {
269			t.Fatalf("S-D 作废后仍应保留完整判定依据: %+v", d)
270		}
271		if d.Results[0].Limit != 8.0 || !d.Results[0].LimitEffective.Equal(at(1, 0)) {
272			t.Fatalf("S-D 的逐项上限与生效时间应保留: %+v", d.Results)
273		}
274	
275		// 同时刻被选中的 S-A 作废：退到该时刻下一份仍有效的已确认样品 S-B，
276		// 而不是更晚的待判定 S-C 或仍保留结果的作废 S-D。
277		if _, err := s.Void("S-A", "采样瓶破损"); err != nil {
278			t.Fatalf("Void S-A: %v", err)
279		}
280		fallback, ok, err := s.LatestResult("P1")
281		if err != nil || !ok {
282			t.Fatalf("S-A 作废后应退到 S-B: %+v ok=%v err=%v", fallback, ok, err)
283		}
284		checkLatestB(t, fallback, t0, "S-A 作废后")
285	
286		// 关闭重开后选择不变，作废状态与退回规则随落盘保持。
287		if err := s.Close(); err != nil {
288			t.Fatalf("Close: %v", err)
289		}
290		s2, err := Open(dir)
291		if err != nil {
292			t.Fatalf("reopen: %v", err)
293		}
294		defer s2.Close()
295		reopened, ok, err := s2.LatestResult("P1")
296		if err != nil || !ok {
297			t.Fatalf("重开后仍应为 S-B: %+v ok=%v err=%v", reopened, ok, err)
298		}
299		checkLatestB(t, reopened, t0, "重开后")
300	
301		// 最后一份有效样品也作废：明确无结果，返回空样品且不报错误。
302		// 更晚的 S-C 仍待判定，其 Exceeded 零值为假不表示达标，不能顶替。
303		if _, err := s2.Void("S-B", "记录错误"); err != nil {
304			t.Fatalf("Void S-B: %v", err)
305		}
306		none, ok, err := s2.LatestResult("P1")
307		if err != nil || ok {
308			t.Fatalf("全部失效时应明确无结果: %+v ok=%v err=%v", none, ok, err)
309		}
310		if none.ID != "" || none.Status != "" || none.Results != nil {
311			t.Fatalf("无结果时应返回空样品，不能带上待判定记录的信息: %+v", none)
312		}
313		pending, err := s2.ListByPoint("P1")
314		if err != nil {
315			t.Fatalf("ListByPoint: %v", err)
316		}
317		var c Sample
318		for _, smp := range pending {
319			if smp.ID == "S-C" {
320				c = smp
321			}
322		}
323		if c.ID != "S-C" {
324			t.Fatalf("列表中缺少 S-C: %+v", pending)
325		}
326		if c.Status != StatusPending || len(c.Results) != 0 || c.Exceeded {
327			t.Fatalf("S-C 应保持待判定、无结论，超标零值不能解释成达标: %+v", c)
328		}
329	}
330	
331	// 该点只有待判定样品、或仅有已作废样品时，查询明确表示无结果：
332	// 返回空样品、ok 为假且不报错。
333	func TestLatestResultWithoutValidConfirmedSample(t *testing.T) {
334		s, _ := open(t)
335		mustPoint(t, s, "P1", "取水口")
336		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
337	
338		// 仅有待判定样品：Exceeded 的零值 false 是“没有结论”，不是达标。
339		mustSample(t, s, "S1", "P1", latestBaseTime(), Measurement{Item: "pH", Value: 7})
340		none, ok, err := s.LatestResult("P1")
341		if err != nil || ok {
342			t.Fatalf("仅待判定时应无结果: %+v ok=%v err=%v", none, ok, err)
343		}
344		if none.ID != "" || none.Status != "" || none.Exceeded || none.Results != nil {
345			t.Fatalf("无结果应返回空样品，不能把待判定零值当达标: %+v", none)
346		}
347	
348		// 确认后又作废：即使判定依据仍保留，也不再是有效结果。
349		if _, err := s.Confirm("S1"); err != nil {
350			t.Fatalf("Confirm: %v", err)
351		}
352		if _, err := s.Void("S1", "采样瓶破损"); err != nil {
353			t.Fatalf("Void: %v", err)
354		}
355		none2, ok, err := s.LatestResult("P1")
356		if err != nil || ok {
357			t.Fatalf("仅作废样品时应无结果: %+v ok=%v err=%v", none2, ok, err)
358		}
359		if none2.ID != "" || none2.Status != "" || none2.Results != nil {
360			t.Fatalf("无结果应返回空样品，不能带回作废记录的判定: %+v", none2)
361		}
362	}
363

