1	package water
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// 本文件围绕“按采样时刻选用限值”的小数秒时间边界补回归保障：
13	// 接受带小数秒的时间，确认时只取采样当时（精确到纳秒的真实时刻）已经生效的
14	// 最近一版限值；同一秒内不同纳秒的采样时刻必须区分，限值生效边界前一纳秒用
15	// 旧版、恰好生效与后一纳秒用新版。录入、确认、查询、作废的既有业务行为不变。
16	
17	const (
18		turbItem = "浊度"
19		flatItem = "pH" // 三份样品里上限始终未变更的对照项目
20	)
21	
22	// turbBoundary 是浊度限值切换的真实时刻：2026-09-10 12:00:00.5 UTC，
23	// 自该时刻的第 500000000 纳秒起上限由 10 改为 5。
24	func turbBoundary() time.Time {
25		return time.Date(2026, 9, 10, 12, 0, 0, 500_000_000, time.UTC)
26	}
27	
28	// checkBoundarySample 完整核对一份双项目样品在纳秒边界下应保存的内容：
29	// 浊度采用 wantTurbLimit（生效时间 wantTurbEff，测量值 7 的超标结论随之而定），
30	// pH 始终使用 6@oldEff 且测量值 6 恰好等于上限、判达标；整份结论只由浊度决定。
31	// 采样时刻必须连小数秒一起保留，逐项依据必须带实际上限数值与准确生效时刻。
32	func checkBoundarySample(t *testing.T, smp Sample, wantID string, sampled time.Time,
33		wantTurbLimit float64, wantTurbEff, oldEff time.Time, label string,
34	) {
35		t.Helper()
36		if smp.ID != wantID || smp.PointID != "P1" || smp.Status != StatusConfirmed || smp.VoidReason != "" {
37			t.Fatalf("%s: 编号、采样点、状态或作废原因错误: %+v", label, smp)
38		}
39		// 采样时间不能丢失小数秒：同一真实时刻且纳秒部分也必须一致。
40		if !smp.SampledAt.Equal(sampled) {
41			t.Fatalf("%s: 采样真实时刻应为 %s，实际 %s", label, sampled, smp.SampledAt)
42		}
43		if smp.SampledAt.Nanosecond() != sampled.Nanosecond() {
44			t.Fatalf("%s: 采样时间丢失小数秒，纳秒部分应 %d 实际 %d",
45				label, sampled.Nanosecond(), smp.SampledAt.Nanosecond())
46		}
47		if len(smp.Measurements) != 2 || len(smp.Results) != 2 {
48			t.Fatalf("%s: 测量或逐项判定数量错误: %+v", label, smp)
49		}
50		ms := map[string]float64{}
51		for _, m := range smp.Measurements {
52			ms[m.Item] = m.Value
53		}
54		if ms[turbItem] != 7 || ms[flatItem] != 6 {
55			t.Fatalf("%s: 原始测量值被改动: %+v", label, smp.Measurements)
56		}
57		rs := map[string]ItemResult{}
58		for _, r := range smp.Results {
59			rs[r.Item] = r
60		}
61		turb, ok := rs[turbItem]
62		if !ok {
63			t.Fatalf("%s: 缺少浊度的逐项判定: %+v", label, smp.Results)
64		}
65		wantTurbExceeded := 7 > wantTurbLimit
66		if turb.Value != 7 || turb.Limit != wantTurbLimit || !turb.LimitEffective.Equal(wantTurbEff) ||
67			turb.Exceeded != wantTurbExceeded {
68			t.Fatalf("%s: 浊度应采用上限 %g（%s 生效），测量值 7 超标=%v，实际 %+v",
69				label, wantTurbLimit, wantTurbEff, wantTurbExceeded, turb)
70		}
71		// 对照项目上限未变更：三份样品都用同一版限值、同一生效时刻，等于上限判达标。
72		flat, ok := rs[flatItem]
73		if !ok {
74			t.Fatalf("%s: 缺少 %s 的逐项判定: %+v", label, flatItem, smp.Results)
75		}
76		if flat.Value != 6 || flat.Limit != 6 || !flat.LimitEffective.Equal(oldEff) || flat.Exceeded {
77			t.Fatalf("%s: 未变更项目应统一使用 6@%s 且等于上限达标，实际 %+v",
78				label, oldEff, flat)
79		}
80		// 另一项达标不能冲掉浊度的超标结论：任一项目超标则整份超标。
81		if smp.Exceeded != wantTurbExceeded {
82			t.Fatalf("%s: 整份结论应为 超标=%v，实际 %v", label, wantTurbExceeded, smp.Exceeded)
83		}
84	}
85	
86	// 同一秒内的三个采样时刻（边界前一纳秒、恰好、后一纳秒）必须各用各的限值：
87	// 前一纳秒仍是旧上限 10（7 ≤ 10 达标），恰好生效与后一纳秒用新上限 5（7 > 5 超标）。
88	// 每份逐项依据保留实际采用的上限数值及准确生效时刻，采样时间保留小数秒；
89	// Confirm 的返回与 ListByPoint 查到的同一记录一致，落盘重开后小数秒不丢。
90	func TestConfirmNanosecondBoundaryWithinSameSecond(t *testing.T) {
91		s, dir := open(t)
92		mustPoint(t, s, "P1", "取水口")
93		oldEff := at(1, 0) // 2026-09-01 UTC，浊度旧版与 pH 唯一一版的生效时间
94		boundary := turbBoundary()
95		mustLimit(t, s, "P1", turbItem, 10, oldEff)
96		mustLimit(t, s, "P1", turbItem, 5, boundary)
97		mustLimit(t, s, "P1", flatItem, 6, oldEff)
98	
99		before := boundary.Add(-1) // 12:00:00.499999999
100		atTime := boundary         // 12:00:00.500000000
101		after := boundary.Add(1)   // 12:00:00.500000001
102		// 三份样品处在同一秒（Unix 秒数相同），仅纳秒部分不同。
103		// 不能只因为年月日时分秒相同就采用同一版限值。
104		if before.Unix() != atTime.Unix() || atTime.Unix() != after.Unix() {
105			t.Fatal("测试前提：三份采样时间应落在同一秒内")
106		}
107		if before.Nanosecond() == atTime.Nanosecond() || atTime.Nanosecond() == after.Nanosecond() {
108			t.Fatal("测试前提：三份采样时间的纳秒部分必须不同")
109		}
110	
111		measure := func() []Measurement {
112			return []Measurement{{Item: turbItem, Value: 7}, {Item: flatItem, Value: 6}}
113		}
114		mustSample(t, s, "S-BEFORE", "P1", before, measure()...)
115		mustSample(t, s, "S-AT", "P1", atTime, measure()...)
116		mustSample(t, s, "S-AFTER", "P1", after, measure()...)
117	
118		confirmed := map[string]Sample{}
119		for _, id := range []string{"S-BEFORE", "S-AT", "S-AFTER"} {
120			smp, err := s.Confirm(id)
121			if err != nil {
122				t.Fatalf("Confirm %s: %v", id, err)
123			}
124			confirmed[id] = smp
125		}
126		// 边界前一纳秒用旧版 10 达标；恰好生效与后一纳秒用新版 5 超标。
127		checkBoundarySample(t, confirmed["S-BEFORE"], "S-BEFORE", before, 10, oldEff, oldEff, "确认返回-前一纳秒")
128		checkBoundarySample(t, confirmed["S-AT"], "S-AT", atTime, 5, boundary, oldEff, "确认返回-恰好生效")
129		checkBoundarySample(t, confirmed["S-AFTER"], "S-AFTER", after, 5, boundary, oldEff, "确认返回-后一纳秒")
130	
131		// 按采样点查询：采样时间从晚到早，差一纳秒也要排出先后，三份各自的采样时刻与测量值不混。
132		list, err := s.ListByPoint("P1")
133		if err != nil || len(list) != 3 {
134			t.Fatalf("ListByPoint: %+v err=%v", list, err)
135		}
136		wantOrder := []string{"S-AFTER", "S-AT", "S-BEFORE"}
137		for i, id := range wantOrder {
138			if list[i].ID != id {
139				t.Fatalf("排列应为 %v（晚到早，纳秒不同即不同时刻），实际 %+v", wantOrder, list)
140			}
141		}
142		// 确认返回的逐项依据和整份结论必须与按点查询到的相应记录一致。
143		listed := map[string]Sample{}
144		for _, smp := range list {
145			listed[smp.ID] = smp
146		}
147		checkBoundarySample(t, listed["S-BEFORE"], "S-BEFORE", before, 10, oldEff, oldEff, "按点查询-前一纳秒")
148		checkBoundarySample(t, listed["S-AT"], "S-AT", atTime, 5, boundary, oldEff, "按点查询-恰好生效")
149		checkBoundarySample(t, listed["S-AFTER"], "S-AFTER", after, 5, boundary, oldEff, "按点查询-后一纳秒")
150		// 最近有效结果指向采样最晚（后一纳秒）的那份超标样品。
151		latest, ok, err := s.LatestResult("P1")
152		if err != nil || !ok {
153			t.Fatalf("最近有效结果应为 S-AFTER: %+v ok=%v err=%v", latest, ok, err)
154		}
155		checkBoundarySample(t, latest, "S-AFTER", after, 5, boundary, oldEff, "最近有效结果")
156	
157		// 小数秒必须实际落盘：数据文件中应能看到三个带不同小数位的时间串，
158		// 限值生效时刻 0.5 与三份采样时刻各自的纳秒都在。
159		data, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
160		if err != nil {
161			t.Fatalf("read data file: %v", err)
162		}
163		for _, want := range []string{
164			"2026-09-10T12:00:00.499999999Z",
165			"2026-09-10T12:00:00.5Z",
166			"2026-09-10T12:00:00.500000001Z",
167		} {
168			if !strings.Contains(string(data), want) {
169				t.Fatalf("落盘数据应保留小数秒时间 %s，实际内容：%s", want, string(data))
170			}
171		}
172	
173		// 关闭后重新打开：小数秒采样时刻、逐项采用的上限与准确生效时间、整份结论原样保留。
174		if err := s.Close(); err != nil {
175			t.Fatalf("Close: %v", err)
176		}
177		s2, err := Open(dir)
178		if err != nil {
179			t.Fatalf("reopen: %v", err)
180		}
181		defer s2.Close()
182		list2, err := s2.ListByPoint("P1")
183		if err != nil || len(list2) != 3 {
184			t.Fatalf("重开后 ListByPoint: %+v err=%v", list2, err)
185		}
186		for _, smp := range list2 {
187			switch smp.ID {
188			case "S-BEFORE":
189				checkBoundarySample(t, smp, "S-BEFORE", before, 10, oldEff, oldEff, "重开-前一纳秒")
190			case "S-AT":
191				checkBoundarySample(t, smp, "S-AT", atTime, 5, boundary, oldEff, "重开-恰好生效")
192			case "S-AFTER":
193				checkBoundarySample(t, smp, "S-AFTER", after, 5, boundary, oldEff, "重开-后一纳秒")
194			default:
195				t.Fatalf("重开后出现意外记录: %+v", smp)
196			}
197		}
198		// 重复确认仍返回已保存的逐项依据，不随后续任何限值变化重算。
199		again, err := s2.Confirm("S-AT")
200		if err != nil {
201			t.Fatalf("重开后重复确认: %v", err)
202		}
203		checkBoundarySample(t, again, "S-AT", atTime, 5, boundary, oldEff, "重开后重复确认")
204	}
205	
206	// 先登记新版本（5@boundary）、之后再乱序补录旧版本（10@更早）时，确认结果仍只由
207	// 各版生效时刻与采样时刻的关系决定，与登记先后无关：旧版补录前，边界前一纳秒的
208	// 样品没有任何已生效上限，必须整次拒绝并保持待判定；补录后再确认才用旧版判达标。
209	// 已用新版确认的恰好/后一纳秒样品，结论与所采用限值不随旧版补录改变。
210	func TestConfirmNanosecondBoundaryBackfillOrder(t *testing.T) {
211		s, _ := open(t)
212		mustPoint(t, s, "P1", "取水口")
213		oldEff := at(1, 0)
214		boundary := turbBoundary()
215		mustLimit(t, s, "P1", flatItem, 6, oldEff)
216		// 先登记新版本，旧版本此刻尚不存在。
217		mustLimit(t, s, "P1", turbItem, 5, boundary)
218	
219		before := boundary.Add(-1)
220		atTime := boundary
221		after := boundary.Add(1)
222		measure := func() []Measurement {
223			return []Measurement{{Item: turbItem, Value: 7}, {Item: flatItem, Value: 6}}
224		}
225		mustSample(t, s, "S-BEFORE", "P1", before, measure()...)
226		mustSample(t, s, "S-AT", "P1", atTime, measure()...)
227		mustSample(t, s, "S-AFTER", "P1", after, measure()...)
228	
229		// 旧版未补录：前一纳秒时新版 5 尚未生效，没有任何适用上限，整次拒绝。
230		got, err := s.Confirm("S-BEFORE")
231		if !errors.Is(err, ErrMissingLimit) {
232			t.Fatalf("旧版补录前边界前一纳秒应缺适用上限，got %+v err=%v", got, err)
233		}
234		if got.ID != "" || got.Status != "" {
235			t.Fatalf("缺适用上限被拒时应返回空样品，got %+v", got)
236		}
237		list, _ := s.ListByPoint("P1")
238		var pending Sample
239		for _, smp := range list {
240			if smp.ID == "S-BEFORE" {
241				pending = smp
242			}
243		}
244		if pending.ID != "S-BEFORE" || pending.Status != StatusPending || len(pending.Results) != 0 || pending.Exceeded {
245			t.Fatalf("被拒样品应保持待判定、无逐项结果与整份结论: %+v", pending)
246		}
247		if !pending.SampledAt.Equal(before) || pending.SampledAt.Nanosecond() != before.Nanosecond() {
248			t.Fatalf("待判定记录的小数秒采样时间丢失: %+v", pending)
249		}
250	
251		// 恰好生效与后一纳秒：新版已生效，正常判为超标并保存。
252		confAt, err := s.Confirm("S-AT")
253		if err != nil {
254			t.Fatalf("Confirm S-AT: %v", err)
255		}
256		checkBoundarySample(t, confAt, "S-AT", atTime, 5, boundary, oldEff, "补录前-恰好生效")
257		confAfter, err := s.Confirm("S-AFTER")
258		if err != nil {
259			t.Fatalf("Confirm S-AFTER: %v", err)
260		}
261		checkBoundarySample(t, confAfter, "S-AFTER", after, 5, boundary, oldEff, "补录前-后一纳秒")
262	
263		// 乱序补录旧版（生效时间远早于 boundary）。
264		mustLimit(t, s, "P1", turbItem, 10, oldEff)
265	
266		// 前一纳秒样品现在应取旧版 10，测量值 7 达标，整份达标。
267		confBefore, err := s.Confirm("S-BEFORE")
268		if err != nil {
269			t.Fatalf("补录旧版后 Confirm S-BEFORE: %v", err)
270		}
271		checkBoundarySample(t, confBefore, "S-BEFORE", before, 10, oldEff, oldEff, "补录后-前一纳秒")
272	
273		// 已确认的两份不重算：仍是新版 5、超标，逐项依据与整份结论保持原样。
274		againAt, err := s.Confirm("S-AT")
275		if err != nil {
276			t.Fatalf("重复确认 S-AT: %v", err)
277		}
278		checkBoundarySample(t, againAt, "S-AT", atTime, 5, boundary, oldEff, "补录后重复确认-恰好生效")
279		againAfter, err := s.Confirm("S-AFTER")
280		if err != nil {
281			t.Fatalf("重复确认 S-AFTER: %v", err)
282		}
283		checkBoundarySample(t, againAfter, "S-AFTER", after, 5, boundary, oldEff, "补录后重复确认-后一纳秒")
284	
285		// 按点查询与各次确认返回一致，顺序按纳秒时刻晚到早。
286		list2, err := s.ListByPoint("P1")
287		if err != nil || len(list2) != 3 {
288			t.Fatalf("ListByPoint: %+v err=%v", list2, err)
289		}
290		listed := map[string]Sample{}
291		for _, smp := range list2 {
292			listed[smp.ID] = smp
293		}
294		checkBoundarySample(t, listed["S-BEFORE"], "S-BEFORE", before, 10, oldEff, oldEff, "按点查询-前一纳秒")
295		checkBoundarySample(t, listed["S-AT"], "S-AT", atTime, 5, boundary, oldEff, "按点查询-恰好生效")
296		checkBoundarySample(t, listed["S-AFTER"], "S-AFTER", after, 5, boundary, oldEff, "按点查询-后一纳秒")
297		if list2[0].ID != "S-AFTER" || list2[1].ID != "S-AT" || list2[2].ID != "S-BEFORE" {
298			t.Fatalf("排列应按纳秒时刻晚到早: %+v", list2)
299		}
300	}
301	
302	// 采样时刻没有任何已生效版本的边界：某项目唯一一版上限比采样时间晚一纳秒才生效，
303	// 即使另一项目能判定，整次确认也必须因缺少适用上限而拒绝：样品保持待判定，
304	// 没有逐项结果或整份结论；既不能借用这个未来版本，也不能把缺失上限当成零。
305	// 重开数据存放后拒绝结论不变；补录一版恰好于采样时刻生效的上限后，对原样品
306	// 再确认才成功，且采用的正是恰好生效这版，晚一纳秒的未来版本仍不被借用。
307	func TestConfirmMissingLimitOneNanosecondBeforeEffective(t *testing.T) {
308		s, dir := open(t)
309		mustPoint(t, s, "P1", "取水口")
310		phEff := at(1, 0)
311		mustLimit(t, s, "P1", "pH", 8, phEff)
312	
313		sampled := turbBoundary() // 12:00:00.5 UTC
314		// 未来版本：比采样时间晚一纳秒生效，故意用北京时间表示同一真实时刻，
315		// 防止实现按“年月日时分秒”的字面量跨时区比较。
316		beijing := time.FixedZone("CST", 8*3600)
317		future := time.Date(2026, 9, 10, 20, 0, 0, 500_000_001, beijing)
318		if !future.Equal(sampled.Add(1)) {
319			t.Fatalf("测试前提：未来版本应等于采样时刻后一纳秒，future=%s sampled=%s", future, sampled)
320		}
321		mustLimit(t, s, "P1", "COD", 30, future)
322	
323		// S1：pH 能判定（7 ≤ 8），COD 只有一版晚一纳秒才生效的上限。
324		mustSample(t, s, "S1", "P1", sampled,
325			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 3})
326		// S2：COD 测量值取负数。若错误地把缺失上限当成零，-1 > 0 为假会“达标”；
327		// 正确行为是缺适用上限照样整次拒绝。
328		mustSample(t, s, "S2", "P1", sampled.Add(0),
329			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: -1})
330	
331		for _, id := range []string{"S1", "S2"} {
332			got, err := s.Confirm(id)
333			if !errors.Is(err, ErrMissingLimit) {
334				t.Fatalf("%s: 只有晚一纳秒才生效的版本时应缺适用上限拒绝，got %+v err=%v", id, got, err)
335			}
336			if got.ID != "" || got.Status != "" || got.Exceeded || len(got.Results) != 0 {
337				t.Fatalf("%s: 被拒确认应返回空样品、不带任何结论，got %+v", id, got)
338			}
339		}
340		// 原样品继续待判定：没有逐项结果或整份达标结论，小数秒采样时间保留。
341		list, err := s.ListByPoint("P1")
342		if err != nil || len(list) != 2 {
343			t.Fatalf("ListByPoint: %+v err=%v", list, err)
344		}
345		for _, smp := range list {
346			if smp.Status != StatusPending || len(smp.Results) != 0 || smp.Exceeded {
347				t.Fatalf("%s: 应保持待判定且无逐项结果/整份结论: %+v", smp.ID, smp)
348			}
349			if !smp.SampledAt.Equal(sampled) || smp.SampledAt.Nanosecond() != sampled.Nanosecond() {
350				t.Fatalf("%s: 小数秒采样时间丢失: %s", smp.ID, smp.SampledAt)
351			}
352		}
353		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
354			t.Fatalf("缺适用上限被拒后不应有最近有效结果: %+v ok=%v err=%v", latest, ok, err)
355		}
356	
357		// 重开数据存放：待判定状态与小数秒采样时间保持，未来版本仍不能借用。
358		if err := s.Close(); err != nil {
359			t.Fatalf("Close: %v", err)
360		}
361		s2, err := Open(dir)
362		if err != nil {
363			t.Fatalf("reopen: %v", err)
364		}
365		defer s2.Close()
366		for _, id := range []string{"S1", "S2"} {
367			if _, err := s2.Confirm(id); !errors.Is(err, ErrMissingLimit) {
368				t.Fatalf("重开后 %s 仍应缺适用上限拒绝，got %v", id, err)
369			}
370		}
371	
372		// 补录一版“恰好”于采样时刻生效的上限（30 那版仍晚一纳秒，不能被借用）。
373		exactEff := sampled
374		mustLimit(t, s2, "P1", "COD", 4, exactEff)
375		want := map[string]float64{"S1": 3, "S2": -1}
376		for id, value := range want {
377			smp, err := s2.Confirm(id)
378			if err != nil {
379				t.Fatalf("补录恰好生效版本后 Confirm %s: %v", id, err)
380			}
381			if smp.Status != StatusConfirmed || smp.Exceeded {
382				t.Fatalf("%s: 两项均应达标、整份达标: %+v", id, smp)
383			}
384			if !smp.SampledAt.Equal(sampled) || smp.SampledAt.Nanosecond() != sampled.Nanosecond() {
385				t.Fatalf("%s: 小数秒采样时间丢失: %s", id, smp.SampledAt)
386			}
387			rs := map[string]ItemResult{}
388			for _, r := range smp.Results {
389				rs[r.Item] = r
390			}
391			cod, ph := rs["COD"], rs["pH"]
392			// 必须采用恰好生效的 4，而不是晚一纳秒的 30；测量值不大于 4 判达标。
393			if cod.Value != value || cod.Limit != 4 || !cod.LimitEffective.Equal(exactEff) || cod.Exceeded {
394				t.Fatalf("%s: COD 应采用恰好生效的 4@%s 且达标，实际 %+v", id, exactEff, cod)
395			}
396			// 另一项照常判定，依据不受影响。
397			if ph.Value != 7 || ph.Limit != 8 || !ph.LimitEffective.Equal(phEff) || ph.Exceeded {
398				t.Fatalf("%s: pH 应采用 8@%s 且达标，实际 %+v", id, phEff, ph)
399			}
400		}
401	}
402	
403	// 采样时间和限值生效时间用不同时区表示同一真实时刻时，边界判定必须只认真实时刻：
404	// 边界前一纳秒仍用旧版 10 达标；恰好生效与后一纳秒无论用哪个时区表示，
405	// 都采用新版 5 并超标，保存的生效时间依据与采样时刻是同一真实时刻。
406	func TestConfirmNanosecondBoundaryAcrossTimeZones(t *testing.T) {
407		boundary := turbBoundary()
408		oldEff := at(1, 0)
409		beijing := time.FixedZone("CST", 8*3600)
410		west5 := time.FixedZone("W5", -5*3600)
411		eastHalf := time.FixedZone("E5h30", 5*3600+30*60)
412	
413		cases := []struct {
414			name                  string
415			sampleZone, limitZone *time.Location
416		}{
417			{"采样UTC_限值北京", time.UTC, beijing},
418			{"采样北京_限值UTC", beijing, time.UTC},
419			{"采样西五区_限值东五半", west5, eastHalf},
420			{"采样与限值都用UTC对照", time.UTC, time.UTC},
421		}
422		for _, c := range cases {
423			t.Run(c.name, func(t *testing.T) {
424				s, _ := open(t)
425				mustPoint(t, s, "P1", "取水口")
426				mustLimit(t, s, "P1", flatItem, 6, oldEff)
427				mustLimit(t, s, "P1", turbItem, 10, oldEff)
428				// 新版生效时间用 limitZone 表示 boundary 这一真实时刻。
429				mustLimit(t, s, "P1", turbItem, 5, boundary.In(c.limitZone))
430	
431				instants := map[string]time.Time{
432					"S-BEFORE": boundary.Add(-1),
433					"S-AT":     boundary,
434					"S-AFTER":  boundary.Add(1),
435				}
436				measure := func() []Measurement {
437					return []Measurement{{Item: turbItem, Value: 7}, {Item: flatItem, Value: 6}}
438				}
439				// 采样时间统一用 sampleZone 表示同一真实时刻。
440				for _, id := range []string{"S-BEFORE", "S-AT", "S-AFTER"} {
441					mustSample(t, s, id, "P1", instants[id].In(c.sampleZone), measure()...)
442				}
443				for _, id := range []string{"S-BEFORE", "S-AT", "S-AFTER"} {
444					smp, err := s.Confirm(id)
445					if err != nil {
446						t.Fatalf("Confirm %s: %v", id, err)
447					}
448					switch id {
449					case "S-BEFORE":
450						checkBoundarySample(t, smp, id, instants[id], 10, oldEff, oldEff, "跨时区-前一纳秒")
451					default:
452						checkBoundarySample(t, smp, id, instants[id], 5, boundary, oldEff, "跨时区-"+id)
453						r := rsByItem(smp.Results)[turbItem]
454						// 保存的生效依据必须与任一时区写法表示的都是同一真实时刻。
455						if !r.LimitEffective.Equal(boundary.In(c.limitZone)) {
456							t.Fatalf("%s: 保存的生效时间与限值登记时刻不是同一真实时刻: %s vs %s",
457								id, r.LimitEffective, boundary.In(c.limitZone))
458						}
459					}
460				}
461				// 时区写法不能改变按真实时刻晚到早的排列与结论。
462				list, err := s.ListByPoint("P1")
463				if err != nil || len(list) != 3 {
464					t.Fatalf("ListByPoint: %+v err=%v", list, err)
465				}
466				wantOrder := []string{"S-AFTER", "S-AT", "S-BEFORE"}
467				for i, id := range wantOrder {
468					if list[i].ID != id {
469						t.Fatalf("跨时区排列应为 %v，实际 %+v", wantOrder, list)
470					}
471				}
472			})
473		}
474	}
475	
476	func rsByItem(rs []ItemResult) map[string]ItemResult {
477		m := make(map[string]ItemResult, len(rs))
478		for _, r := range rs {
479			m[r.Item] = r
480		}
481		return m
482	}
