316		reconfirmed2, err := reopened.Confirm("S1")
317		if !errors.Is(err, ErrVoided) {
318			t.Fatalf("重开后再次确认仍应返回作废错误, got %v", err)
319		}
320		checkEmptySample(t, reconfirmed2, "重开后再次确认")
321		list3, err := reopened.ListByPoint("P1")
322		if err != nil || len(list3) != 2 {
323			t.Fatalf("重开后重报不应产生新样品: %+v err=%v", list3, err)
324		}
325	}
326	
327	// 同一编号重报已作废样品时，只要一个测量值不同（即使其他内容全部一致，
328	// 无论改动的是超标项还是恰好等于上限的达标项），都必须按现有的
329	// ErrSampleConflict 整体拒绝并返回空样品。拒绝不留痕：原作废记录的状态、
330	// 原因、测量、逐项依据与整份超标标记不变，按点列表中该编号仍只有一份，
331	// 最近有效结果也不改变。拒绝之后再次提交合法的原内容（可带换序、空白、
332	// 另一时区的等价差别），仍返回同一份作废记录。
333	func TestResubmitVoidedConflictRejectsAndKeepsRecord(t *testing.T) {
334		s, _ := open(t)
335		mustPoint(t, s, "P1", "取水口")
336		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
337		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
338		mustSample(t, s, "S0", "P1", at(5, 0),
339			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 20})
340		earlier, err := s.Confirm("S0")
341		if err != nil {
342			t.Fatalf("Confirm S0: %v", err)
343		}
344		mustSample(t, s, "S1", "P1", at(10, 0),
345			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
346		if _, err := s.Confirm("S1"); err != nil {
347			t.Fatalf("Confirm S1: %v", err)
348		}
349		voided, err := s.Void("S1", "采样瓶破损")
350		if err != nil {
351			t.Fatalf("Void S1: %v", err)
352		}
353	
354		// 每次被拒绝后，作废记录与最近有效结果都必须原封不动。
355		assertUntouched := func(label string) {
356			t.Helper()
357			list, err := s.ListByPoint("P1")
358			if err != nil || len(list) != 2 {
359				t.Fatalf("%s: ListByPoint 应仍只有 S0、S1 两份: %+v err=%v",
360					label, list, err)
361			}
362			checkVoidedS1(t, list[0], label+"按点查询中的 S1")
363			if !reflect.DeepEqual(list[0], voided) {
364				t.Fatalf("%s: 作废记录被改动:\n got %+v\nwant %+v",
365					label, list[0], voided)
366			}
367			latest, ok, err := s.LatestResult("P1")
368			if err != nil || !ok {
369				t.Fatalf("%s: 最近有效结果应仍指向 S0: %+v ok=%v err=%v",
370					label, latest, ok, err)
371			}
372			checkEarlierS0(t, latest, label+"最近有效结果")
373			if !reflect.DeepEqual(latest, earlier) {
374				t.Fatalf("%s: 最近有效结果被改动:\n got %+v\nwant %+v",
375					label, latest, earlier)
376			}
377		}
378	
379		// 1) 超标项 pH 改值（9 -> 10），其他内容一致：内容冲突。
380		conflictPH, err := s.SubmitSample(" S1 ", "P1", at(10, 0),
381			Measurement{Item: " pH ", Value: 10}, Measurement{Item: "COD", Value: 30})
382		if !errors.Is(err, ErrSampleConflict) {
383			t.Fatalf("pH 改值重报应报样品内容冲突, got %v", err)
384		}
385		checkEmptySample(t, conflictPH, "pH 改值重报")
386		assertUntouched("pH 改值被拒绝后")
387	
388		// 2) 恰好等于上限的达标项 COD 改值（30 -> 31），其他内容一致：同样冲突。
389		conflictCOD, err := s.SubmitSample("S1", "P1", at(10, 0),
390			Measurement{Item: "pH", Value: 9}, Measurement{Item: " COD ", Value: 31})
391		if !errors.Is(err, ErrSampleConflict) {
392			t.Fatalf("COD 改值重报应报样品内容冲突, got %v", err)
393		}
394		checkEmptySample(t, conflictCOD, "COD 改值重报")
395		assertUntouched("COD 改值被拒绝后")
396	
397		// 3) 拒绝之后提交合法原内容（换序、空白、另一时区），
398		//    仍返回同一份作废记录，资格不恢复，依据与排列保持首次保存的样子。
399		cst := time.FixedZone("CST", 8*3600)
400		again, err := s.SubmitSample("  S1  ", " P1 ",
401			time.Date(2026, 9, 10, 8, 0, 0, 0, cst),
402			Measurement{Item: "COD", Value: 30}, Measurement{Item: " pH ", Value: 9})
403		if err != nil {
404			t.Fatalf("拒绝后重报合法原内容不应失败: %v", err)
405		}
406		checkVoidedS1(t, again, "拒绝后合法重报")
407		if !reflect.DeepEqual(again, voided) {
408			t.Fatalf("拒绝后合法重报应返回同一份作废记录:\n got %+v\nwant %+v",
409				again, voided)
410		}
411		list, err := s.ListByPoint("P1")
412		if err != nil || len(list) != 2 {
413			t.Fatalf("合法重报不应产生新样品: %+v err=%v", list, err)
414		}
415	}
416	
417	// 从未确认就作废的样品 S2（pH 9、COD 30，采样时刻两项上限均已适用，
418	// 但作废前没有保存过任何判定依据），合法重报后仍必须没有逐项判定依据，
419	// 状态仍是已作废，整份超标标记保持作废前的零值 false——该 false 只是
420	// 保留下来的原值，既不是达标结论也不能被重报补成结论。该点没有其他
421	// 有效已确认样品时，最近结果明确返回空样品、ok 为假且不报错；
422	// 对它再确认仍是 ErrVoided 加空样品。内容冲突拒绝不留痕，
423	// 之后合法重报仍返回同一份无依据的作废记录。
424	func TestResubmitPendingVoidedKeepsNoBasisAndLatestEmpty(t *testing.T) {
425		s, dir := open(t)
426		mustPoint(t, s, "P1", "取水口")
427		// 两项上限在采样时刻都已适用：若重报错误地触发重新判定，就会凭空
428		// 生成超标结论，本测试就是要堵住这条路。
429		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
430		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
431	
432		mustSample(t, s, "S2", "P1", at(12, 0),
433			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
434		voided, err := s.Void(" S2 ", " 录入信息有误 ")
435		if err != nil {
436			t.Fatalf("Void S2: %v", err)
437		}
438		checkPendingVoided := func(smp Sample, label string) {
439			t.Helper()
440			if smp.ID != "S2" || smp.PointID != "P1" || smp.Status != StatusVoided {
441				t.Fatalf("%s: 应返回原作废记录且资格不恢复: %+v", label, smp)
442			}
443			if smp.VoidReason != "录入信息有误" {
444				t.Fatalf("%s: 作废原因应原样保留: %+v", label, smp)
445			}
446			if !smp.SampledAt.Equal(at(12, 0)) {
447				t.Fatalf("%s: 采样时间被改动: %+v", label, smp)
448			}
449			// 作废前没有判定依据，重报不能凭空补出逐项结论或整份超标标记。
450			if len(smp.Results) != 0 || smp.Exceeded {
451				t.Fatalf("%s: 从未确认即作废的样品重报后仍应无判定依据、超标标记保持原值: %+v",
452					label, smp)
453			}
454			if len(smp.Measurements) != 2 {
455				t.Fatalf("%s: 原测量值应保留: %+v", label, smp)
456			}
457			got := make([]string, len(smp.Measurements))
458			for i, m := range smp.Measurements {
459				got[i] = m.Item
460			}
461			if !reflect.DeepEqual(got, []string{"pH", "COD"}) {
462				t.Fatalf("%s: 测量排列应保持首次录入顺序: %v", label, got)
463			}
464			if smp.Measurements[0].Value != 9 || smp.Measurements[1].Value != 30 {
465				t.Fatalf("%s: 原测量值被改动: %+v", label, smp.Measurements)
466			}
467		}
468		checkPendingVoided(voided, "直接作废返回")
469	
470		// 该点没有其他有效已确认样品：最近结果明确无结果，空样品、ok 假、无错误。
471		// 作废记录里为假的超标标记不能推导出达标。
472		none, ok, err := s.LatestResult("P1")
473		if err != nil || ok {
474			t.Fatalf("应明确无结果: %+v ok=%v err=%v", none, ok, err)
475		}
476		checkEmptySample(t, none, "无最近有效结果")
477	
478		cst := time.FixedZone("CST", 8*3600) // 2026-09-12 08:00 +08:00 == 00:00 UTC
479		legit := []struct {
480			name      string
481			id        string
482			point     string
483			sampledAt time.Time
484			ms        []Measurement
485		}{
486			{
487				name:      "原内容重报",
488				id:        "S2",
489				point:     "P1",
490				sampledAt: at(12, 0),
491				ms: []Measurement{
492					{Item: "pH", Value: 9},
493					{Item: "COD", Value: 30},
494				},
495			},
496			{
497				name:      "换序空白另一时区",
498				id:        "  S2 ",
499				point:     " P1 ",
500				sampledAt: time.Date(2026, 9, 12, 8, 0, 0, 0, cst),
501				ms: []Measurement{
502					{Item: " COD ", Value: 30},
503					{Item: " pH ", Value: 9},
504				},
505			},
506		}
507		for _, c := range legit {
508			got, err := s.SubmitSample(c.id, c.point, c.sampledAt, c.ms...)
509			if err != nil {
510				t.Fatalf("重报原内容（%s）不应被拒绝: %v", c.name, err)
511			}
512			checkPendingVoided(got, "重报（"+c.name+"）")
513			if !reflect.DeepEqual(got, voided) {
514				t.Fatalf("重报（%s）应返回同一份作废记录:\n got %+v\nwant %+v",
515					c.name, got, voided)
516			}
517		}
518	
519		// 一个测量值不同即冲突拒绝，返回空样品，拒绝不生成任何判定依据。
520		conflict, err := s.SubmitSample("S2", "P1", at(12, 0),
521			Measurement{Item: "pH", Value: 9.5}, Measurement{Item: "COD", Value: 30})
522		if !errors.Is(err, ErrSampleConflict) {
523			t.Fatalf("改值重报应报样品内容冲突, got %v", err)
524		}
525		checkEmptySample(t, conflict, "改值重报")
526		list, err := s.ListByPoint("P1")
527		if err != nil || len(list) != 1 {
528			t.Fatalf("拒绝重报不应留下新记录: %+v err=%v", list, err)
529		}
530		checkPendingVoided(list[0], "冲突被拒后按点查询")
531		if none, ok, err := s.LatestResult("P1"); err != nil || ok {
532			t.Fatalf("冲突被拒后仍应无最近有效结果: %+v ok=%v err=%v", none, ok, err)
533		}
534	
535		// 再提交合法原内容，仍返回同一份无依据的作废记录。
536		again, err := s.SubmitSample("S2", "P1", at(12, 0),
537			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
538		if err != nil {
539			t.Fatalf("拒绝后重报合法原内容不应失败: %v", err)
540		}
541		checkPendingVoided(again, "拒绝后合法重报")
542		if !reflect.DeepEqual(again, voided) {
543			t.Fatalf("拒绝后合法重报应返回同一份作废记录:\n got %+v\nwant %+v",
544				again, voided)
545		}
546	
547		// 对重报后的作废样品再确认：仍是作废错误加空样品，不会借确认补出结论。
548		reconfirmed, err := s.Confirm("S2")
549		if !errors.Is(err, ErrVoided) {
550			t.Fatalf("作废样品再次确认应返回作废错误, got %v", err)
551		}
552		checkEmptySample(t, reconfirmed, "再次确认")
553	
554		// 关闭重开后，作废状态、无依据与“最近结果为空”都随落盘保持，
555		// 新进程里重报仍返回同一份记录。
556		if err := s.Close(); err != nil {
557			t.Fatalf("Close: %v", err)
558		}
559		reopened, err := Open(dir)
560		if err != nil {
561			t.Fatalf("重新 Open: %v", err)
562		}
563		t.Cleanup(func() { reopened.Close() })
564	
565		list2, err := reopened.ListByPoint("P1")
566		if err != nil || len(list2) != 1 {
567			t.Fatalf("重开后 ListByPoint 应仍只有 S2: %+v err=%v", list2, err)
568		}
569		checkPendingVoided(list2[0], "重开后按点查询")
570		if none, ok, err := reopened.LatestResult("P1"); err != nil || ok {
571			t.Fatalf("重开后仍应明确无结果: %+v ok=%v err=%v", none, ok, err)
572		}
573		reopenedAgain, err := reopened.SubmitSample(" S2 ", " P1 ",
574			time.Date(2026, 9, 12, 8, 0, 0, 0, cst),
575			Measurement{Item: "COD", Value: 30}, Measurement{Item: "pH", Value: 9})
576		if err != nil {
577			t.Fatalf("重开后重报原内容: %v", err)
578		}
579		checkPendingVoided(reopenedAgain, "重开后重报")
580		if !reflect.DeepEqual(reopenedAgain, voided) {
581			t.Fatalf("重开后重报应返回同一份作废记录:\n got %+v\nwant %+v",
582				reopenedAgain, voided)
583		}
584	}
